package com.bank.trading;

import java.util.logging.*;

public class PeakDemo {
    private static final Logger log = Logger.getLogger(PeakDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Hourly trade volumes across the day (unsorted, neighbors differ)
        int[] volumes = {120, 350, 800, 640, 200, 900, 500};

        VolumeAnalyzer analyzer = new VolumeAnalyzer();
        int peakIndex = analyzer.findPeak(volumes);

        log.info("Found a local peak hour");
        log.info("Peak at hour index " + peakIndex + " with volume " + volumes[peakIndex]);
    }
}

// ─── Would be in service/VolumeAnalyzer.java ───
class VolumeAnalyzer {
    // Binary search on the slope. O(log n) time, O(1) space.
    int findPeak(int[] arr) {
        int low = 0, high = arr.length - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;   // mid+1 is always valid here
            if (arr[mid] < arr[mid + 1]) {
                low = mid + 1;                  // climbing: peak is to the right
            } else {
                high = mid;                     // peak is at mid or to the left
            }
        }
        return low;                             // low == high == a peak index
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
